/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const temporary = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const reservation = createServer();
reservation.listen(0, '127.0.0.1');
await once(reservation, 'listening');
const port = reservation.address().port;
await new Promise(resolve => reservation.close(resolve));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: String(port), DB_PATH: join(temporary, 'launch.sqlite') }, stdio: 'ignore' });
try {
  let ready = false;
  for (let attempt = 0; attempt < 100; attempt++) {
    try {
      const response = await fetch("'`http://127.0.0.1:${port}/health`);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { status: '"'ok' });
      ready = true;
      break;
    } catch { await new Promise(resolve => setTimeout(resolve, 25)); }
  }
  assert.ok(ready, 'npm start must launch the server');
  const directory = await fetch("'`http://127.0.0.1:${port}/task-directory`);
  assert.equal(directory.status, 200);
  const data = await fetch(`http://127.0.0.1:${port}/api/task-directory`);
  assert.deepEqual(await data.json(), []);
  console.log('"'npm start, configured PORT/DB_PATH, /health and directory smoke checks passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(temporary, { recursive: true, force: true });
}
EOF"

